-- Final BBA core/pathway practice set. Original learning questions, not official MUST exam questions.
WITH quiz_seed(course_code,title,description) AS (
 VALUES
 ('BFB3362','Ace Practice · Decision Making in Projects','Original practice on project decision criteria, trade-offs and uncertainty.'),
 ('BFB3363','Ace Practice · Project Appraisal (Project Pathway)','Original practice on project benefits, opportunity cost and appraisal under uncertainty.'),
 ('BFB3402','Ace Practice · Management of Organizational Change','Original practice on readiness, stakeholder engagement, communication and change evaluation.'),
 ('BFB3420','Ace Practice · Leadership and Team Building','Original practice on team development, leadership, role clarity and constructive conflict.'),
 ('BFC3425','Ace Practice · Management Accounting','Original practice on contribution, relevant costs, budgets and activity-based costing.'),
 ('BFC3426','Ace Practice · Advanced Accounting II','Original practice on consolidation, intragroup eliminations and group reporting concepts.'),
 ('BFB3412','Ace Practice · Project Finance','Original practice on project-finance structures, cash-flow risk and debt service.'),
 ('BFB3413','Ace Practice · Project Resources Management','Original practice on resource planning, allocation, leveling and team capacity.'),
 ('BFB3469','Ace Practice · Workplace Counselling','Original practice on professional boundaries, confidentiality, listening and referral.'),
 ('BFC3327','Ace Practice · Financial Accounting Theory','Original practice on reporting concepts, qualitative characteristics and accounting theory.'),
 ('BFC3329','Ace Practice · Advanced Taxation','Original conceptual practice on tax planning, transfer pricing and compliance; not tax advice.'),
 ('BFB3462','Ace Practice · Project Management Decision Making Models','Original practice on decision trees, scoring models and sensitivity analysis.'),
 ('BFB3463','Ace Practice · Projects Organization, Management and Leadership','Original practice on project structures, responsibilities and leadership.'),
 ('BFB3464','Ace Practice · Global Project Management','Original practice on cross-border project risk, coordination and local compliance.')
),
inserted_quizzes AS (
 INSERT INTO public.ace_quizzes(title,course_code,description,status)
 SELECT s.title,s.course_code,s.description,'published' FROM quiz_seed s
 WHERE NOT EXISTS(SELECT 1 FROM public.ace_quizzes q WHERE q.title=s.title AND q.course_code=s.course_code)
 RETURNING id,course_code,title
),
quiz_ids AS (
 SELECT id,course_code,title FROM inserted_quizzes
 UNION ALL
 SELECT q.id,q.course_code,q.title FROM public.ace_quizzes q JOIN quiz_seed s ON s.course_code=q.course_code AND s.title=q.title
 WHERE NOT EXISTS(SELECT 1 FROM inserted_quizzes i WHERE i.id=q.id)
),
question_seed(course_code,quiz_title,sort_order,prompt,options,correct_index,explanation) AS (
 VALUES
 -- Decision Making in Projects
 ('BFB3362','Ace Practice · Decision Making in Projects',1,'A project team scores three options against weighted criteria. The primary purpose of weighting criteria is to:',ARRAY['Represent the relative importance of criteria in a transparent comparison','Guarantee the highest-scoring option cannot fail','Hide trade-offs from stakeholders','Replace evidence with the project manager’s preference']::text[],0,'A weighted decision matrix makes priorities explicit; scores and weights still depend on sound evidence and assumptions.',1),
 ('BFB3362','Ace Practice · Decision Making in Projects',2,'When a project decision depends on uncertain future demand, the team should first:',ARRAY['Identify plausible scenarios, assumptions and decision consequences','Treat the most optimistic forecast as certain','Ignore downside outcomes','Select the option with the most complex model']::text[],0,'Structured scenario analysis makes uncertainty visible and helps compare decisions under different possible conditions.',2),
 ('BFB3362','Ace Practice · Decision Making in Projects',3,'A sensitivity analysis changes one key assumption at a time to understand:',ARRAY['How much the decision outcome depends on that assumption','Whether every input is perfectly accurate','The legal status of the project sponsor','The number of team meetings']::text[],0,'Sensitivity analysis tests the effect of input changes on results and highlights assumptions that deserve closer attention.',3),
 ('BFB3362','Ace Practice · Decision Making in Projects',4,'Why should decision criteria be agreed before scoring project options?',ARRAY['To reduce post-hoc bias and ensure options are judged against consistent priorities','To guarantee that the preferred option wins','To prevent stakeholders from asking questions','To make all criteria equally important']::text[],0,'Pre-agreed criteria improve consistency and reduce the temptation to change rules after seeing which option leads.',4),
 ('BFB3362','Ace Practice · Decision Making in Projects',5,'A model recommends an option but the result changes sharply when one uncertain input changes slightly. The decision-maker should:',ARRAY['Investigate the assumption, test scenarios and consider whether more information is worth obtaining','Accept the output without question','Delete the input from the model','Assume sensitivity proves the model is useless']::text[],0,'High sensitivity signals that the decision may depend on uncertain inputs and may warrant better data, safeguards or staged commitment.',5),
 -- Project Appraisal, Project Pathway
 ('BFB3363','Ace Practice · Project Appraisal (Project Pathway)',1,'A project appraisal should compare relevant future incremental costs and benefits because:',ARRAY['The decision should reflect cash flows that change as a result of undertaking the project','All historical costs must be recovered by every project','Sunk costs always determine the best choice','Only accounting depreciation matters']::text[],0,'Incremental analysis focuses on future costs and benefits affected by the decision; sunk costs are not changed by the choice.',1),
 ('BFB3363','Ace Practice · Project Appraisal (Project Pathway)',2,'A public project provides unpriced health benefits to a community. A social appraisal should:',ARRAY['Consider material external social benefits as well as financial flows','Ignore benefits without invoices','Treat all public benefits as zero','Use private profit as the only criterion']::text[],0,'Social appraisal considers effects on society, including external benefits and costs that may not appear in private cash flows.',2),
 ('BFB3363','Ace Practice · Project Appraisal (Project Pathway)',3,'A project has an attractive base-case NPV but fails under a small fall in expected demand. This suggests:',ARRAY['Demand assumptions are material and the project may need redesign, evidence or risk mitigation','The NPV calculation can never be useful','Demand does not affect project value','The project has no risk']::text[],0,'A fragile base case indicates material sensitivity to demand and should inform due diligence and risk response.',3),
 ('BFB3363','Ace Practice · Project Appraisal (Project Pathway)',4,'Opportunity cost in project appraisal is:',ARRAY['The value of the best alternative use of a resource that is forgone','Every historical expense recorded by the organisation','The interest rate charged by a supplier in all cases','A cost that is always paid in cash']::text[],0,'Opportunity cost reflects the best alternative forgone, even when no direct cash payment occurs.',4),
 ('BFB3363','Ace Practice · Project Appraisal (Project Pathway)',5,'Why should a project appraisal state its assumptions and data sources?',ARRAY['So reviewers can challenge inputs, understand limitations and test scenarios','To make the appraisal impossible to reproduce','To avoid accountability for the recommendation','To hide uncertainty from decision-makers']::text[],0,'Transparent assumptions make the analysis auditable, reproducible and open to sensitivity testing.',5),
 -- Organizational Change
 ('BFB3402','Ace Practice · Management of Organizational Change',1,'A technically sound system rollout fails because employees do not understand why it is needed. The most immediate gap is:',ARRAY['Change communication and engagement','Database normalisation','Tax depreciation','The project title']::text[],0,'People need a clear case for change and an opportunity to understand how it affects their work.',1),
 ('BFB3402','Ace Practice · Management of Organizational Change',2,'Stakeholder analysis during change helps leaders:',ARRAY['Identify who is affected, likely concerns and appropriate engagement approaches','Assume every employee has identical needs','Avoid discussing the change','Replace training with an announcement']::text[],0,'Stakeholder analysis helps tailor involvement, communication and support to different impacts and concerns.',2),
 ('BFB3402','Ace Practice · Management of Organizational Change',3,'A pilot rollout is useful because it can:',ARRAY['Reveal implementation issues and allow learning before wider deployment','Guarantee there will be no resistance','Replace the need for monitoring','Ensure every user adopts the system immediately']::text[],0,'A pilot creates a controlled opportunity to test workflows, collect feedback and adjust the implementation plan.',3),
 ('BFB3402','Ace Practice · Management of Organizational Change',4,'Resistance to change should generally be treated as:',ARRAY['Information to investigate, since it may reflect real risks, loss or unclear communication','Proof that employees are always unreasonable','A reason to conceal all future changes','A signal to ignore operational evidence']::text[],0,'Resistance can reveal legitimate concerns or unmet needs; leaders should listen, assess evidence and respond appropriately.',4),
 ('BFB3402','Ace Practice · Management of Organizational Change',5,'After a new process is introduced, leaders should evaluate:',ARRAY['Adoption, outcomes, unintended effects and whether further support is needed','Only whether the launch meeting occurred','Only the number of emails sent','Whether feedback can be deleted']::text[],0,'Change evaluation checks whether intended outcomes are achieved and whether adjustments or reinforcement are needed.',5),
 -- Leadership and Team Building
 ('BFB3420','Ace Practice · Leadership and Team Building',1,'A team charter is useful because it clarifies:',ARRAY['Purpose, roles, decision rules and working expectations','Only the team’s favourite colours','The final project profit with certainty','All individual private information']::text[],0,'A team charter establishes shared expectations and reduces ambiguity about how members will work together.',1),
 ('BFB3420','Ace Practice · Leadership and Team Building',2,'Constructive conflict is most likely when team members:',ARRAY['Challenge ideas respectfully and use evidence while maintaining respect for people','Attack colleagues personally','Hide concerns until the project ends','Treat the most senior view as automatically correct']::text[],0,'Task-focused disagreement can improve decisions when people remain respectful and evaluate evidence.',2),
 ('BFB3420','Ace Practice · Leadership and Team Building',3,'A leader who changes the amount of direction and support based on a team’s task competence and confidence is using:',ARRAY['A situational approach to leadership','A fixed rule that every team needs the same supervision','A method of financial auditing','A form of inventory valuation']::text[],0,'Situational leadership approaches adapt direction and support to the task and the team’s readiness, rather than applying one style everywhere.',3),
 ('BFB3420','Ace Practice · Leadership and Team Building',4,'A team is repeatedly missing deadlines because responsibilities overlap. The best first intervention is to:',ARRAY['Clarify ownership, dependencies and hand-offs','Increase the number of status meetings without changing roles','Remove all milestones','Assume motivation is the only problem']::text[],0,'Clear responsibilities and hand-offs help prevent duplicated work and tasks falling between roles.',4),
 ('BFB3420','Ace Practice · Leadership and Team Building',5,'Effective delegation should include:',ARRAY['A clear outcome, appropriate authority, constraints and agreed follow-up','A vague request with no authority','Transfer of every form of accountability','No feedback until the deadline']::text[],0,'Delegation works when expected outcomes and decision authority are clear and progress is reviewed appropriately.',5),
 -- Management Accounting
 ('BFC3425','Ace Practice · Management Accounting',1,'A product sells for KSh 900 and has variable cost of KSh 540 per unit. Contribution per unit is:',ARRAY['KSh 360','KSh 540','KSh 900','KSh 1,440']::text[],0,'Contribution per unit = selling price − variable cost = 900 − 540 = KSh 360.',1),
 ('BFC3425','Ace Practice · Management Accounting',2,'For a short-term decision, a relevant cost is generally a cost that:',ARRAY['Differs between the alternatives and relates to the future decision','Has already been incurred and cannot be changed','Is identical under every option','Is always a fixed cost']::text[],0,'Relevant costs are future costs that differ between alternatives; sunk costs are normally irrelevant to the choice.',2),
 ('BFC3425','Ace Practice · Management Accounting',3,'A favourable material price variance can occur when:',ARRAY['The actual purchase price per unit is below the standard price, for the quantity purchased','More material is wasted than expected','Actual output is always lower than budget','The standard price is removed from the budget']::text[],0,'A favourable price variance arises when the actual price is below standard, though the quality and usage effects should also be considered.',3),
 ('BFC3425','Ace Practice · Management Accounting',4,'Activity-based costing allocates overhead by using:',ARRAY['Cost drivers linked to activities that consume resources','Only direct labour hours in every business','The selling price of the product only','The chief executive’s preference']::text[],0,'ABC traces overhead to activities and allocates costs using drivers that reflect resource consumption.',4),
 ('BFC3425','Ace Practice · Management Accounting',5,'A manager should be evaluated using measures the manager can reasonably influence because this supports:',ARRAY['Responsibility accounting and fairer performance assessment','Ignoring all budgets','Automatic profit maximisation','Eliminating the need for controls']::text[],0,'Controllability helps align performance evaluation with the decisions and resources a manager can influence.',5),
 -- Advanced Accounting II
 ('BFC3426','Ace Practice · Advanced Accounting II',1,'In consolidated financial statements, the parent and controlled subsidiary are generally presented as:',ARRAY['A single economic group, subject to consolidation requirements','Unrelated entities with no combined reporting','Only the parent’s cash account','Two statements that must never be combined']::text[],0,'Consolidation presents the parent and its controlled subsidiaries as one economic entity under the applicable reporting framework.',1),
 ('BFC3426','Ace Practice · Advanced Accounting II',2,'Why are intragroup sales and balances generally eliminated on consolidation?',ARRAY['They are internal to the group and are not transactions with external parties','They are always illegal','They are the same as tax payments','They must be reported twice to improve transparency']::text[],0,'Consolidated statements report the group’s transactions with external parties, so intragroup effects are eliminated as required.',2),
 ('BFC3426','Ace Practice · Advanced Accounting II',3,'Goodwill in a business combination generally arises when:',ARRAY['The consideration and other relevant acquisition measures exceed the recognised net identifiable assets under the applicable method','A company receives ordinary sales revenue','Inventory is sold below cost','The subsidiary pays a dividend']::text[],0,'Goodwill generally reflects the excess arising in acquisition accounting after measuring identifiable net assets and other relevant components.',3),
 ('BFC3426','Ace Practice · Advanced Accounting II',4,'A non-controlling interest represents:',ARRAY['The equity in a subsidiary not attributable directly or indirectly to the parent','A supplier’s unpaid invoice only','The parent’s full ownership percentage','A tax penalty']::text[],0,'Non-controlling interest represents the portion of a subsidiary’s equity not attributable to the parent under the applicable framework.',4),
 ('BFC3426','Ace Practice · Advanced Accounting II',5,'Why must an accountant identify the applicable reporting framework before preparing advanced financial statements?',ARRAY['Recognition, measurement, presentation and disclosure requirements depend on the applicable standards','Every country and entity uses identical rules in every circumstance','The framework affects only font size','It eliminates the need for professional judgement']::text[],0,'The applicable framework determines the requirements and judgement needed for compliant reporting.',5),
 -- Project Finance
 ('BFB3412','Ace Practice · Project Finance',1,'Project finance is commonly structured around:',ARRAY['The project’s expected cash flows and risk allocation, often through a special-purpose vehicle','Only the personal salary of the project manager','The parent company’s logo','A guarantee that project revenue cannot fall']::text[],0,'Project-finance lenders place substantial focus on the project’s cash flows, contracts and allocation of risks.',1),
 ('BFB3412','Ace Practice · Project Finance',2,'Debt service coverage ratio compares cash available for debt service with:',ARRAY['Scheduled debt principal and interest payments','Total staff headcount','The project’s social-media followers','Only the original construction budget']::text[],0,'DSCR measures cash available to service debt relative to scheduled debt obligations; definitions vary by financing agreement.',2),
 ('BFB3412','Ace Practice · Project Finance',3,'A bankability review should examine:',ARRAY['Revenue assumptions, contracts, risks, permits, financing terms and ability to service debt','Only whether the project has a name','Only sunk costs','Whether risk disclosures can be removed']::text[],0,'Lenders assess the project’s commercial viability, legal permissions, risk allocation and cash-flow capacity.',3),
 ('BFB3412','Ace Practice · Project Finance',4,'A well-designed project contract allocates a risk primarily to the party that:',ARRAY['Can best manage, control or absorb that risk, subject to negotiation and incentives','Has the least information about it in every case','Is always the smallest supplier','Has no ability to influence the outcome']::text[],0,'Efficient risk allocation considers control, capacity and incentives rather than transferring every risk indiscriminately.',4),
 ('BFB3412','Ace Practice · Project Finance',5,'A project’s forecast cash flows fall below the level needed to meet scheduled debt payments. This raises a concern about:',ARRAY['Debt-service capacity and potential covenant or default risk','The project’s font choice','Whether the team has a meeting agenda','The colour of financial charts']::text[],0,'Insufficient cash flow can impair debt service and trigger covenant breaches or default depending on the financing terms.',5),
 -- Project Resources Management
 ('BFB3413','Ace Practice · Project Resources Management',1,'Resource leveling is used to:',ARRAY['Adjust schedules to address resource over-allocation, potentially changing dates','Increase every task duration without analysis','Remove the need for a resource plan','Guarantee that all work finishes earlier']::text[],0,'Resource leveling resolves over-allocation and can change the project schedule or critical path.',1),
 ('BFB3413','Ace Practice · Project Resources Management',2,'A RACI matrix clarifies who is responsible, accountable, consulted and:',ARRAY['Informed','Insured','Invoiced','Interviewed']::text[],0,'RACI clarifies participation and accountability for tasks and decisions.',2),
 ('BFB3413','Ace Practice · Project Resources Management',3,'A project repeatedly assigns the same specialist to simultaneous critical tasks. The best response is to:',ARRAY['Replan priorities and capacity, consider sequencing or alternatives, and make trade-offs explicit','Assume the specialist can complete every task at once','Hide the conflict from the sponsor','Remove the resource estimates']::text[],0,'Resource conflicts require explicit prioritisation, sequencing, capacity changes or other justified trade-offs.',3),
 ('BFB3413','Ace Practice · Project Resources Management',4,'Resource utilisation should be monitored alongside workload and outcomes because:',ARRAY['High utilisation alone can create queues, fatigue and delays when there is no capacity buffer','100% utilisation guarantees perfect delivery','Idle capacity is always wasteful','Workload has no relationship to performance']::text[],0,'Maximising utilisation without buffers can increase waiting time and reduce resilience to variability.',4),
 ('BFB3413','Ace Practice · Project Resources Management',5,'A skills matrix is useful for project resource planning because it:',ARRAY['Shows capability coverage and helps identify training or staffing gaps','Replaces all performance conversations','Guarantees every skill is interchangeable','Lists only staff salaries']::text[],0,'A skills matrix makes capability and coverage visible so the team can plan assignments, training and backup capacity.',5),
 -- Workplace Counselling
 ('BFB3469','Ace Practice · Workplace Counselling',1,'A workplace counsellor should normally explain confidentiality and its limits:',ARRAY['At the beginning of the process so the person understands how information may be handled','Only after sharing the information','Never, because confidentiality has no limits','Only to the person’s colleagues']::text[],0,'Clear boundaries help establish trust and explain any legal, safety or policy exceptions before sensitive information is shared.',1),
 ('BFB3469','Ace Practice · Workplace Counselling',2,'Active listening during a counselling conversation includes:',ARRAY['Attending, reflecting key points and asking open clarifying questions','Immediately prescribing a solution without understanding the concern','Sharing the conversation with the whole office','Making a diagnosis outside one’s competence']::text[],0,'Active listening helps the person explain their concerns and supports accurate understanding without premature judgement.',2),
 ('BFB3469','Ace Practice · Workplace Counselling',3,'If an employee’s needs are outside the counsellor’s professional competence, the appropriate response is to:',ARRAY['Discuss a suitable referral or additional support within the applicable policy and consent requirements','Pretend to have the required expertise','Promise that the issue will never be escalated in any circumstance','Publish the employee’s details']::text[],0,'Professional boundaries require recognising limitations and facilitating appropriate support or referral.',3),
 ('BFB3469','Ace Practice · Workplace Counselling',4,'A manager who is also conducting a formal disciplinary investigation should be careful about acting as a confidential counsellor because:',ARRAY['The roles may conflict and undermine trust or procedural fairness','The two roles are always identical','Counselling removes all employment procedures','Employees never need privacy']::text[],0,'Support and formal investigation have different purposes; role clarity helps manage conflicts and protect fair process.',4),
 ('BFB3469','Ace Practice · Workplace Counselling',5,'A supportive workplace response to distress should:',ARRAY['Respect privacy, listen without judgement and explain appropriate support options','Assume the employee is at fault','Share sensitive information as a warning to others','Guarantee an outcome that cannot be controlled']::text[],0,'Respectful support protects dignity and connects the person with appropriate options without overpromising.',5),
 -- Financial Accounting Theory
 ('BFC3327','Ace Practice · Financial Accounting Theory',1,'Relevance and faithful representation are commonly treated as:',ARRAY['Fundamental qualitative characteristics of useful financial information','Two types of tax rate','Inventory valuation methods only','Names for bank reconciliation items']::text[],0,'The conceptual framework emphasises relevance and faithful representation as fundamental characteristics of useful financial information.',1),
 ('BFC3327','Ace Practice · Financial Accounting Theory',2,'Agency theory in financial reporting is concerned in part with:',ARRAY['Potential conflicts between principals and agents who have different information or incentives','How inventory is physically counted only','The number of accounting software screens','How to calculate sales tax rates']::text[],0,'Agency theory studies relationships where agents make decisions on behalf of principals and incentives or information may diverge.',2),
 ('BFC3327','Ace Practice · Financial Accounting Theory',3,'A positive accounting theory generally seeks to:',ARRAY['Explain or predict accounting choices and behaviour','Prescribe the only morally correct accounting policy in every situation','Replace all empirical evidence with opinion','Calculate a company’s daily cash balance']::text[],0,'Positive accounting theory aims to explain or predict observed accounting choices, whereas normative approaches recommend what should be done.',3),
 ('BFC3327','Ace Practice · Financial Accounting Theory',4,'Why does substance over form matter in financial reporting?',ARRAY['Economic substance may differ from a transaction’s legal form and can affect faithful reporting','Legal documents never matter','It permits transactions to be omitted','It guarantees that all estimates are exact']::text[],0,'Reporting should reflect the economic substance of relevant transactions under the applicable standards, not rely only on labels.',4),
 ('BFC3327','Ace Practice · Financial Accounting Theory',5,'Accounting standards aim to improve comparability mainly by:',ARRAY['Providing common recognition, measurement, presentation and disclosure requirements','Ensuring every company has identical business operations','Eliminating all estimates and judgement','Making every financial statement equally profitable']::text[],0,'Common standards support more consistent reporting, although judgement, estimates and differing business circumstances remain.',5),
 -- Advanced Taxation
 ('BFC3329','Ace Practice · Advanced Taxation',1,'Transfer-pricing rules generally seek to ensure that related-party cross-border transactions are priced consistently with:',ARRAY['The arm’s-length principle under the applicable tax law','A price chosen solely to minimise tax with no evidence','The lowest price in every market','A fixed global rate for all goods']::text[],0,'The arm’s-length principle compares related-party conditions with those that independent parties would agree in comparable circumstances.',1),
 ('BFC3329','Ace Practice · Advanced Taxation',2,'Which approach best distinguishes lawful tax planning from tax evasion?',ARRAY['Tax planning uses choices permitted by law; evasion involves unlawful concealment or misrepresentation','Both terms always mean the same thing','Tax evasion is lawful whenever a return is filed','Tax planning means never keeping records']::text[],0,'The distinction depends on the law and facts; unlawful concealment or false statements can constitute evasion.',2),
 ('BFC3329','Ace Practice · Advanced Taxation',3,'Why should a tax professional verify the relevant tax period and current law before advising a client?',ARRAY['Rates, definitions, thresholds and effective dates can change through legislation and guidance','All tax laws remain unchanged forever','Historical textbook rates always override legislation','The date of a transaction never matters']::text[],0,'Tax analysis depends on the rules in force for the relevant period, including amendments and transitional provisions.',3),
 ('BFC3329','Ace Practice · Advanced Taxation',4,'A defensible tax position should be supported by:',ARRAY['Relevant records, legal analysis and evidence for the treatment adopted','An unsupported verbal promise','Deleted invoices','A tax calculation copied from another country without review']::text[],0,'Documentation and reasoned analysis support compliance and the ability to explain a position if challenged.',4),
 ('BFC3329','Ace Practice · Advanced Taxation',5,'When a taxpayer disagrees with a tax assessment, the most appropriate next step is to:',ARRAY['Review the assessment and follow the applicable statutory objection and appeal procedures within the relevant deadlines','Ignore the notice indefinitely','Destroy supporting records','Assume an informal phone call automatically suspends every deadline']::text[],0,'Tax disputes are governed by statutory procedures and timelines; current law and official guidance should be checked promptly.',5),
 -- Project Management Decision Making Models
 ('BFB3462','Ace Practice · Project Management Decision Making Models',1,'A decision tree is especially useful when:',ARRAY['Choices lead to uncertain events and different possible outcomes','Every outcome is already certain','No alternative decisions exist','A project has no dependencies']::text[],0,'Decision trees structure alternatives, chance events and outcomes so expected values or other criteria can be compared.',1),
 ('BFB3462','Ace Practice · Project Management Decision Making Models',2,'Expected monetary value is calculated by:',ARRAY['Multiplying each monetary outcome by its probability and summing the results','Choosing the largest possible outcome only','Adding all probabilities without considering outcomes','Dividing the project budget by the number of team members']::text[],0,'EMV weights each outcome by its probability and sums the weighted values; it is an expectation, not a guarantee.',2),
 ('BFB3462','Ace Practice · Project Management Decision Making Models',3,'A weighted scoring model is most defensible when:',ARRAY['Criteria, weights and scoring rules are explicit and tested for sensitivity','Weights are changed after each option is scored to favour a preferred choice','Only one option is ever considered','Scores are treated as objective facts without judgement']::text[],0,'Transparent criteria and sensitivity checks make assumptions and judgement visible to decision-makers.',3),
 ('BFB3462','Ace Practice · Project Management Decision Making Models',4,'Scenario analysis differs from one-variable sensitivity analysis because it can:',ARRAY['Change several related assumptions together to represent a coherent possible future','Guarantee that the base case will occur','Remove uncertainty from the project','Replace every financial calculation']::text[],0,'Scenario analysis considers coherent combinations of assumptions, while simple sensitivity analysis often varies one input at a time.',4),
 ('BFB3462','Ace Practice · Project Management Decision Making Models',5,'A decision model should be treated as:',ARRAY['A structured aid to judgement whose assumptions and limits need review','An unquestionable substitute for accountable decision-makers','A guarantee of the best outcome','A way to avoid recording a decision rationale']::text[],0,'Models organise evidence and trade-offs but depend on assumptions and do not replace accountable judgement.',5),
 -- Projects Organization, Management and Leadership
 ('BFB3463','Ace Practice · Projects Organization, Management and Leadership',1,'In a matrix project structure, a team member may report to:',ARRAY['Both a functional manager and a project manager, requiring clear authority and priorities','No manager under any circumstance','Only the customer in every case','A regulator rather than the organisation']::text[],0,'Matrix structures share people across functions and projects, so decision rights and priorities must be clarified.',1),
 ('BFB3463','Ace Practice · Projects Organization, Management and Leadership',2,'A project sponsor typically:',ARRAY['Champions the project, secures organisational support and helps resolve escalated issues','Performs every technical task personally','Replaces all users and stakeholders','Approves changes without regard to governance']::text[],0,'Sponsors provide senior ownership and organisational support while the project manager coordinates delivery.',2),
 ('BFB3463','Ace Practice · Projects Organization, Management and Leadership',3,'A RACI matrix helps resolve ambiguity by identifying who is responsible, accountable, consulted and:',ARRAY['Informed','Insured','Invoiced','Interviewed']::text[],0,'RACI clarifies participation and accountability for tasks and decisions.',3),
 ('BFB3463','Ace Practice · Projects Organization, Management and Leadership',4,'When two functional managers compete for the same project resource, the project manager should:',ARRAY['Escalate through agreed governance with evidence about priorities, dependencies and impacts','Promise the same resource to both teams without a plan','Hide the conflict from the sponsor','Change the project objectives without approval']::text[],0,'Shared-resource conflicts require transparent trade-offs and decisions at the appropriate authority level.',4),
 ('BFB3463','Ace Practice · Projects Organization, Management and Leadership',5,'Project leadership is most effective when communication:',ARRAY['Clarifies the goal, decisions, responsibilities and routes for raising issues','Is limited to one launch email','Uses ambiguity to preserve flexibility','Avoids stakeholders who disagree']::text[],0,'Clear, two-way communication aligns the team and surfaces problems early.',5),
 -- Global Project Management
 ('BFB3464','Ace Practice · Global Project Management',1,'A global project team operates across several time zones. A useful coordination practice is to:',ARRAY['Agree working-hour expectations, rotate inconvenient meeting times where practical and document decisions asynchronously','Require one region to attend every meeting at night','Avoid written decisions','Assume all time zones share the same business hours']::text[],0,'Time-zone-aware planning and clear asynchronous records reduce exclusion and coordination delays.',1),
 ('BFB3464','Ace Practice · Global Project Management',2,'A project entering a new country should check local legal and regulatory requirements because:',ARRAY['Permits, employment, tax, data and procurement rules can differ by jurisdiction','The home-country rules automatically apply everywhere','Local laws matter only after a dispute','A contract can always override mandatory law']::text[],0,'Cross-border projects must identify applicable local and cross-border requirements before commitments are made.',2),
 ('BFB3464','Ace Practice · Global Project Management',3,'A supplier currency weakens against the project’s reporting currency. The project cost impact depends in part on:',ARRAY['Contract currency, pricing terms, timing and any currency hedges','The supplier’s logo','The number of project status meetings','Whether the project has a work breakdown structure']::text[],0,'Exchange-rate exposure depends on currency of payment, contract terms, cash-flow timing and risk-management arrangements.',3),
 ('BFB3464','Ace Practice · Global Project Management',4,'Why should global project managers avoid assuming that one communication style works everywhere?',ARRAY['Expectations about hierarchy, feedback, timing and disagreement can vary across people and contexts','Every culture is internally identical','Translation removes all cultural differences','Communication has no effect on delivery']::text[],0,'Adaptation and explicit norms help teams collaborate without relying on stereotypes about individuals.',4),
 ('BFB3464','Ace Practice · Global Project Management',5,'A disruption affects a critical supplier in another region. A resilient global project plan should:',ARRAY['Assess alternatives, lead times, dependencies and recovery actions before the disruption escalates','Assume global supply chains never fail','Remove the risk register','Wait until every alternative is unavailable']::text[],0,'Resilience depends on visibility into dependencies and practical recovery options, including alternate suppliers where feasible.',5)
),
questions_added AS (
 INSERT INTO public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order)
 SELECT q.id,qs.prompt,to_jsonb(qs.options),qs.correct_index,qs.explanation,qs.sort_order
 FROM question_seed qs JOIN quiz_ids q ON q.course_code=qs.course_code AND q.title=qs.quiz_title
 WHERE NOT EXISTS(SELECT 1 FROM public.ace_questions existing WHERE existing.quiz_id=q.id)
 RETURNING id
)
SELECT (SELECT count(*) FROM inserted_quizzes) quizzes_created,
       (SELECT count(*) FROM questions_added) questions_created;